-- Migration: Year 2 - Endocrine Pathology MCQ Bank (PART 2: 61-140)
-- Topics: Diabetes Mellitus, Pancreatic Tumors, MEN Syndromes, Neuroblastoma, Craniopharyngioma
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- 1. Ensure Topic "Endocrine Pathology" exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Endocrine Pathology', 'endocrine-pathology', 3, 2, 40)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    -- 2. Insert MCQs (61-140)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    
    -- ENDOCRINE PANCREAS: DIABETES MELLITUS TYPE 1 & 2
    (v_topic_id, 'Which histological finding is classic for Type 1 Diabetes Mellitus?', '["Amyloid deposition in islets", "Islet leukocytic infiltration (Insulitis)", "Hyperplasia of beta cells", "Fibrosis of exocrine pancreas"]', 1, 'Type 1 DM is an autoimmune destruction of beta cells characterized by T-lymphocyte infiltration (insulitis).'),
    (v_topic_id, 'Which histological finding is classic for Type 2 Diabetes Mellitus?', '["Islet leukocytic infiltration", "Amyloid deposition in islets", "Alpha cell hyperplasia", "Pancreatic calcifications"]', 1, 'In Type 2 DM, amylin (co-secreted with insulin) accumulates as amyloid in the islets.'),
    (v_topic_id, 'A patient presents with Kussmaul respirations, fruity breath odor, and severe dehydration. What is the primary driving factor for ketone production?', '["Excess Insulin", "Lack of Glucagon", "Increased hormone-sensitive lipase activity due to lack of insulin", "Decreased fatty acid oxidation"]', 2, 'Lack of insulin removes inhibition on hormone-sensitive lipase, causing free fatty acids to flood the liver, where they are converted to ketones.'),
    (v_topic_id, 'Hyperosmolar Hyperglycemic State (HHS) is more common in Type 2 DM than Type 1 DM because?', '["Type 2 DM patients have more severe insulin resistance", "Trace amounts of endogenous insulin in Type 2 DM prevent lipolysis and ketogenesis", "Type 2 DM patients consume more glucose", "Type 2 DM patients have impaired renal function"]', 1, 'Even small amounts of insulin in T2DM are sufficient to inhibit hormone-sensitive lipase, preventing significant ketogenesis, but not enough to prevent severe hyperglycemia.'),
    (v_topic_id, 'Which HLA types confer the highest genetic risk for Type 1 Diabetes Mellitus?', '["HLA-B27", "HLA-DR2 and DR3", "HLA-DR3 and DR4", "HLA-DQ2 and DQ8"]', 2, 'HLA-DR3 and HLA-DR4 are strongly associated with Type 1 DM.'),

    -- DIABETIC COMPLICATIONS
    (v_topic_id, 'Nonenzymatic glycosylation of large and medium-sized vessels in Diabetes leads to?', '["Hyaline arteriolosclerosis", "Atherosclerosis", "Hyperplastic arteriolosclerosis", "Monckeberg arteriosclerosis"]', 1, 'Glycosylation of large/medium vessels causes accelerated atherosclerosis, leading to myocardial infarctions and peripheral vascular disease.'),
    (v_topic_id, 'Nonenzymatic glycosylation of small vessels (arterioles) in Diabetes leads to?', '["Hyaline arteriolosclerosis", "Atherosclerosis", "Hyperplastic arteriolosclerosis", "Fibrinoid necrosis"]', 0, 'Hyaline arteriolosclerosis (especially efferent arteriole in the kidney) is classic for microvascular diabetic damage.'),
    (v_topic_id, 'Nodular glomerulosclerosis with Kimmelstiel-Wilson nodules is diagnostic of?', '["Lupus Nephritis", "Diabetic Nephropathy", "IgA Nephropathy", "Amyloidosis"]', 1, 'Kimmelstiel-Wilson nodules (eosinophilic nodular glomerulosclerosis) are pathognomonic for diabetic nephropathy.'),
    (v_topic_id, 'Osmotic damage in diabetes (e.g., cataracts, neuropathy) is mediated by which enzyme?', '["Aldose Reductase", "Hexokinase", "Glucokinase", "Sorbitol Dehydrogenase"]', 0, 'Aldose reductase converts glucose to sorbitol. Tissues lacking sorbitol dehydrogenase (lens, retina, Schwann cells) accumulate sorbitol, causing osmotic damage.'),
    (v_topic_id, 'A diabetic patient develops "stocking-glove" sensory loss. What is the mechanism?', '["Microvascular ischemia to nerves", "Osmotic damage via sorbitol accumulation in Schwann cells", "Both A and B", "Autoimmune destruction of myelin"]', 2, 'Diabetic peripheral neuropathy is multifactorial, involving both osmotic damage (sorbitol) to Schwann cells and ischemic damage from arteriolosclerosis of the vasa nervorum.'),

    -- PANCREATIC NEUROENDOCRINE TUMORS
    (v_topic_id, 'A patient presents with recurrent episodes of confusion and lethargy that resolve upon eating. Fasting glucose is 40 mg/dL, with elevated C-peptide and elevated insulin. Diagnosis?', '["Exogenous Insulin Administration", "Insulinoma", "Glucagonoma", "Factitious Hypoglycemia"]', 1, 'Endogenous insulin production (Insulinoma) is characterized by high insulin and high C-peptide. Exogenous insulin would show low C-peptide.'),
    (v_topic_id, 'A patient presents with necrolytic migratory erythema, weight loss, deep vein thrombosis, and new-onset diabetes. Diagnosis?', '["Insulinoma", "Zollinger-Ellison Syndrome", "Glucagonoma", "VIPoma"]', 2, 'The classic presentation of a Glucagonoma (alpha-cell tumor) includes Dermatitis (necrolytic migratory erythema), Diabetes, DVT, and Depression.'),
    (v_topic_id, 'A patient presents with severe, refractory peptic ulcers, including ulcers in the jejunum. Fasting serum gastrin is markedly elevated. Diagnosis?', '["Helicobacter pylori infection", "NSAID-induced ulcers", "Zollinger-Ellison Syndrome", "VIPoma"]', 2, 'ZE Syndrome is caused by a gastrinoma, leading to massive acid hypersecretion and atypical/refractory ulcers. A secretin stimulation test will show a paradoxical increase in gastrin.'),
    (v_topic_id, 'A patient presents with copious, watery diarrhea (tea-colored), hypokalemia, and achlorhydria (WDHA syndrome). Diagnosis?', '["Carcinoid Syndrome", "VIPoma", "Somatostatinoma", "Cholera"]', 1, 'Vasoactive Intestinal Peptide (VIP)oma causes Watery Diarrhea, Hypokalemia, and Achlorhydria (WDHA syndrome).'),
    (v_topic_id, 'A patient presents with diabetes mellitus, steatorrhea, and gallstones. Diagnosis?', '["Glucagonoma", "Insulinoma", "Somatostatinoma", "VIPoma"]', 2, 'Somatostatinomas inhibit insulin (causing diabetes), cholecystokinin (causing gallstones), and secretin/pancreatic enzymes (causing steatorrhea).'),

    -- MULTIPLE ENDOCRINE NEOPLASIA (MEN) SYNDROMES
    (v_topic_id, 'MEN Type 1 (Wermer Syndrome) includes which triad of tumors?', '["Pituitary, Parathyroid, Pancreatic", "Parathyroid, Pheochromocytoma, Medullary Thyroid", "Pheochromocytoma, Medullary Thyroid, Mucosal Neuromas", "Pituitary, Parathyroid, Pheochromocytoma"]', 0, 'The 3 Ps: Pituitary adenoma, Parathyroid hyperplasia/adenoma, Pancreatic endocrine tumors (e.g., ZE syndrome, insulinoma).'),
    (v_topic_id, 'MEN Type 2A (Sipple Syndrome) includes which triad?', '["Pituitary, Parathyroid, Pancreatic", "Parathyroid Hyperplasia, Pheochromocytoma, Medullary Thyroid Carcinoma", "Pheochromocytoma, Medullary Thyroid Carcinoma, Mucosal Neuromas", "Pheochromocytoma, Pancreatic, Pituitary"]', 1, 'MEN 2A features Medullary thyroid carcinoma (100%), Pheochromocytoma, and Parathyroid hyperplasia.'),
    (v_topic_id, 'MEN Type 2B is characterized by which of the following instead of Parathyroid involvement?', '["Pituitary Adenomas", "Mucosal Neuromas and Marfanoid Habitus", "Pancreatic Tumors", "Adrenocortical Carcinoma"]', 1, 'MEN 2B includes Medullary thyroid carcinoma, Pheochromocytoma, Mucosal Neuromas (oral/intestinal ganglioneuromatosis), and a Marfanoid body habitus.'),
    (v_topic_id, 'Both MEN 2A and 2B are caused by mutations in which gene?', '["MEN1 gene", "VHL gene", "RET proto-oncogene", "NF1 gene"]', 2, 'Activating (gain-of-function) mutations in the RET receptor tyrosine kinase are responsible for MEN 2 syndromes.'),
    (v_topic_id, 'Which intervention is recommended for children identified with a RET mutation?', '["Prophylactic parathyroidectomy", "Prophylactic thyroidectomy", "Annual adrenal screening only", "No intervention until symptoms arise"]', 1, 'Because medullary thyroid carcinoma is highly aggressive and almost certain in RET mutation carriers, prophylactic thyroidectomy is performed in infancy/early childhood.'),

    -- PEDIATRIC ENDOCRINE: NEUROBLASTOMA & CRANIOPHARYNGIOMA
    (v_topic_id, 'A 2-year-old child presents with a firm, irregular abdominal mass that crosses the midline. Urine homovanillic acid (HVA) and vanillylmandelic acid (VMA) are elevated. Diagnosis?', '["Wilms Tumor", "Neuroblastoma", "Pheochromocytoma", "Adrenocortical Carcinoma"]', 1, 'Neuroblastoma is the most common tumor of the adrenal medulla in children. Unlike Wilms tumor, it often crosses the midline.'),
    (v_topic_id, 'Which oncogene amplification is a marker for a poor prognosis in Neuroblastoma?', '["c-myc", "N-myc", "L-myc", "RET"]', 1, 'N-myc amplification is associated with rapid progression and poor survival in neuroblastoma.'),
    (v_topic_id, 'Histologically, Neuroblastoma is characterized by?', '["Homer-Wright rosettes", "Flexner-Wintersteiner rosettes", "Call-Exner bodies", "Psammoma bodies"]', 0, 'Homer-Wright rosettes (tumor cells surrounding a central core of neuropil) are classic for neuroblastoma (and medulloblastoma).'),
    (v_topic_id, 'A 10-year-old child presents with bitemporal hemianopsia and growth retardation. Imaging shows a calcified cystic mass in the suprasellar region. Diagnosis?', '["Pituitary Adenoma", "Craniopharyngioma", "Glioblastoma Multiforme", "Rathke Cleft Cyst"]', 1, 'Craniopharyngiomas are benign tumors derived from remnants of Rathke pouch. They frequently calcify and contain cholesterol crystals ("motor oil" fluid).'),
    (v_topic_id, 'Craniopharyngioma arises from remnants of?', '["Neural crest cells", "Endoderm of the primitive pharynx", "Surface ectoderm (Rathke pouch)", "Neuroectoderm"]', 2, 'Rathke pouch is an invagination of surface ectoderm that forms the anterior pituitary.'),

    -- MISCELLANEOUS PITUITARY & ADRENAL
    (v_topic_id, 'A patient presents with severe short stature. Growth hormone levels are highly elevated, but IGF-1 levels are extremely low. Diagnosis?', '["Pituitary Dwarfism", "Laron Syndrome", "Achondroplasia", "Constitutional Growth Delay"]', 1, 'Laron syndrome is a form of dwarfism caused by defective Growth Hormone Receptors, leading to high GH but failure to produce IGF-1 in the liver.'),
    (v_topic_id, 'A patient with sudden onset of severe headache, visual impairment, and features of hypopituitarism (hypotension, shock). They have a known pituitary adenoma. Diagnosis?', '["Sheehan Syndrome", "Pituitary Apoplexy", "Subarachnoid Hemorrhage", "Meningitis"]', 1, 'Pituitary apoplexy is sudden hemorrhage into a pre-existing pituitary adenoma, presenting as a neurological and endocrine emergency.'),
    (v_topic_id, 'An obese female presents with headaches. MRI shows a pituitary gland that is flattened against the wall of the sella turcica, appearing "empty". She has normal pituitary function. Diagnosis?', '["Sheehan Syndrome", "Primary Empty Sella Syndrome", "Pituitary Apoplexy", "Craniopharyngioma"]', 1, 'Empty Sella Syndrome occurs when an arachnoid herniation compresses the pituitary. It is often asymptomatic and incidental in obese women.'),
    (v_topic_id, 'Which of the following is an expected lab finding in Primary Adrenal Insufficiency (Addison Disease) but NOT in Secondary Adrenal Insufficiency?', '["Hyponatremia", "Hyperkalemia", "Hypoglycemia", "Low Cortisol"]', 1, 'Secondary AI (pituitary failure) only lacks ACTH (cortisol deficit). Aldosterone is regulated by the Renin-Angiotensin system and remains intact, so K+ is usually normal. Primary AI lacks both cortisol and aldosterone (leading to hyperkalemia).'),
    (v_topic_id, 'A patient with severe tuberculosis develops hyperkalemia, hyponatremia, and non-anion gap metabolic acidosis. The primary pathological process in their adrenal glands is?', '["Caseating Granulomas", "Autoimmune destruction", "Metastatic infiltration", "Hemorrhagic infarction"]', 0, 'Tuberculosis is a major cause of Addison disease worldwide, causing destruction of the adrenal cortex by caseating granulomas.'),

    -- CALCIUM, PARATHYROID, AND VITAMIN D
    (v_topic_id, 'A patient presents with asymptomatic hypercalcemia. Lab results show mildly elevated Ca2+, low urine Ca2+, and normal/high-normal PTH. Diagnosis?', '["Primary Hyperparathyroidism", "Familial Hypocalciuric Hypercalcemia (FHH)", "Vitamin D Toxicity", "Milk-Alkali Syndrome"]', 1, 'FHH is a benign autosomal dominant mutation in the Calcium-Sensing Receptor (CaSR) in the parathyroid and kidneys, leading to a higher set-point for calcium homeostasis.'),
    (v_topic_id, 'The active form of Vitamin D (1,25-dihydroxycholecalciferol) is produced by which enzyme in the kidney?', '["25-hydroxylase", "1-alpha-hydroxylase", "24-hydroxylase", "7-alpha-hydroxylase"]', 1, '1-alpha-hydroxylase in the proximal tubule converts 25-OH Vitamin D to the active 1,25-OH form. This enzyme is stimulated by PTH.'),
    (v_topic_id, 'Which of the following hormones inhibits osteoclast activity and is used as a tumor marker for medullary thyroid carcinoma?', '["Parathyroid Hormone", "Calcitonin", "Thyroxine", "Aldosterone"]', 1, 'Calcitonin is secreted by parafollicular C-cells of the thyroid and lowers serum calcium by inhibiting osteoclasts.'),

    -- ECTOPIC HORMONE SYNDROMES
    (v_topic_id, 'A patient with a lung mass develops Cushing syndrome. The tumor cells stain positively for synaptophysin and chromogranin. What is the most likely tumor?', '["Squamous Cell Carcinoma", "Small Cell Lung Carcinoma", "Adenocarcinoma", "Large Cell Carcinoma"]', 1, 'Small Cell Lung Carcinoma is a neuroendocrine tumor that frequently secretes ectopic ACTH (or ADH).'),
    (v_topic_id, 'A patient with Squamous Cell Lung Carcinoma develops hypercalcemia. What is the mediator?', '["Ectopic PTH", "PTH-related peptide (PTHrP)", "1,25-dihydroxyvitamin D", "Bone metastases solely"]', 1, 'Squamous cell carcinomas often secrete PTHrP, which mimics PTH, leading to hypercalcemia, low phosphate, and low endogenous PTH.'),
    (v_topic_id, 'A patient with episodic flushing, watery diarrhea, and right-sided valvular heart disease. Diagnosis?', '["VIPoma", "Carcinoid Syndrome", "Pheochromocytoma", "Mastocytosis"]', 1, 'Carcinoid Syndrome (due to serotonin secretion) only occurs when a carcinoid tumor metastasizes to the liver or arises outside the GI tract, bypassing hepatic metabolism.'),
    (v_topic_id, 'What is the diagnostic urine marker for Carcinoid Syndrome?', '["Vanillylmandelic Acid (VMA)", "Homovanillic Acid (HVA)", "5-Hydroxyindoleacetic Acid (5-HIAA)", "Metanephrines"]', 2, '5-HIAA is the primary metabolite of serotonin and is elevated in the urine in carcinoid syndrome.'),
    (v_topic_id, 'Why does Carcinoid heart disease primarily affect the right side of the heart?', '["The left side has higher pressure preventing valve damage", "Serotonin is inactivated by MAO in the lungs", "Serotonin only targets tricuspid receptors", "It affects both sides equally"]', 1, 'Serotonin in the venous blood reaches the right heart, causing fibrosis (tricuspid regurgitation, pulmonary stenosis). It is then cleared by Monoamine Oxidase (MAO) in the lungs, sparing the left heart.'),

    -- ADVANCED THYROID
    (v_topic_id, 'Which drug inhibits both thyroid peroxidase and peripheral conversion of T4 to T3?', '["Methimazole", "Propylthiouracil (PTU)", "Propranolol", "Levothyroxine"]', 1, 'PTU inhibits TPO (synthesis) and 5''-deiodinase (peripheral conversion). Methimazole only inhibits TPO.'),
    (v_topic_id, 'A pregnant patient in her first trimester requires treatment for hyperthyroidism. Which drug is preferred?', '["Methimazole", "Propylthiouracil (PTU)", "Radioactive Iodine", "Amiodarone"]', 1, 'PTU is preferred in the first trimester because Methimazole is associated with aplasia cutis (congenital skin defect). Methimazole is used in the 2nd/3rd trimesters.'),
    (v_topic_id, 'Which of the following antiarrhythmics can cause both hyperthyroidism and hypothyroidism?', '["Sotalol", "Flecainide", "Amiodarone", "Verapamil"]', 2, 'Amiodarone is 40% iodine by weight and can cause hypothyroidism (Wolff-Chaikoff effect) or hyperthyroidism (Jod-Basedow effect or destructive thyroiditis).'),
    (v_topic_id, 'T3 resin uptake test is used to measure?', '["Total T4", "Free T4", "Thyroid Binding Globulin (TBG) capacity", "TSH levels"]', 2, 'T3 resin uptake indirectly measures TBG. If TBG is high (e.g., pregnancy, OCPs), resin uptake is low because the added radioactive T3 binds to the abundant TBG instead of the resin.'),
    
    -- ADVANCED DIABETES
    (v_topic_id, 'What is the mechanism of action of Metformin?', '["Stimulates beta cells to release insulin", "Inhibits hepatic gluconeogenesis and increases peripheral insulin sensitivity", "Inhibits alpha-glucosidase in the brush border", "Agonist of PPAR-gamma"]', 1, 'Metformin acts primarily by decreasing hepatic glucose production (inhibiting gluconeogenesis).'),
    (v_topic_id, 'A diabetic patient is started on an oral hypoglycemic and develops lactic acidosis. Which drug is most likely responsible?', '["Glipizide", "Pioglitazone", "Metformin", "Acarbose"]', 2, 'Metformin carries a risk of lactic acidosis, especially in patients with renal insufficiency, because it inhibits gluconeogenesis from lactate.'),
    (v_topic_id, 'Which class of antidiabetic drugs is associated with an increased risk of euglycemic diabetic ketoacidosis and recurrent UTIs?', '["Sulfonylureas", "SGLT2 inhibitors", "GLP-1 agonists", "DPP-4 inhibitors"]', 1, 'SGLT2 inhibitors (e.g., Canagliflozin) block renal glucose reabsorption, leading to glycosuria (UTIs, yeast infections) and altered glucagon/insulin ratios (euglycemic DKA).'),
    (v_topic_id, 'What is the mechanism of action of Sulfonylureas (e.g., Glyburide)?', '["Close ATP-sensitive K+ channels in beta cells, causing depolarization", "Open ATP-sensitive K+ channels, causing hyperpolarization", "Inhibit DPP-4 enzyme", "Increase incretin effect"]', 0, 'Sulfonylureas close the K+ channel, depolarizing the cell, which opens voltage-gated Ca2+ channels, triggering insulin exocytosis.'),

    -- PARATHYROID AND BONE
    (v_topic_id, 'A patient presents with bone pain, hearing loss, and an enlarged skull (hat size increased). Lab results show isolated high Alkaline Phosphatase with normal Calcium, Phosphorus, and PTH. Diagnosis?', '["Osteitis Fibrosa Cystica", "Paget Disease of Bone", "Osteopetrosis", "Multiple Myeloma"]', 1, 'Paget Disease (Osteitis Deformans) involves disorganized bone remodeling. Ca2+, PO4, and PTH are typically normal, but ALP is very high due to extreme osteoblast activity.'),
    (v_topic_id, 'Which cell type is primarily abnormal in Paget Disease of Bone?', '["Osteoblast", "Osteoclast", "Osteocyte", "Chondrocyte"]', 1, 'The disease starts with a wildly overactive osteoclastic phase, followed by disorganized osteoblastic bone formation (mosaic pattern).'),
    (v_topic_id, 'A patient with end-stage renal disease on dialysis develops severe bone pain and cystic lesions. What is the pathogenesis?', '["Primary Hyperparathyroidism", "Secondary Hyperparathyroidism leading to Osteitis Fibrosa Cystica", "Metastatic calcification", "Paget Disease"]', 1, 'Renal osteodystrophy is driven by secondary hyperparathyroidism (due to high PO4 and low active Vit D), causing severe bone resorption.'),

    -- MISC PATHOLOGY
    (v_topic_id, 'Which endocrine disorder is associated with autoimmune polyendocrine syndrome type 1 (APS-1)?', '["Hyperthyroidism", "Chronic mucocutaneous candidiasis, Hypoparathyroidism, and Addison disease", "Diabetes Insipidus", "Acromegaly"]', 1, 'APS-1 (AIRE gene mutation) classically presents with candidiasis, autoimmune hypoparathyroidism, and adrenal insufficiency.'),
    (v_topic_id, 'Autoimmune polyendocrine syndrome type 2 (APS-2) typically includes?', '["Addison disease, Autoimmune thyroid disease, and Type 1 DM", "Hypoparathyroidism and Candidiasis", "Pheochromocytoma and Medullary CA", "Zollinger-Ellison and Prolactinoma"]', 0, 'APS-2 (more common, HLA-DR3/DR4 associated) features Addison disease along with autoimmune thyroid disease (Schmidt syndrome) and/or T1DM.'),
    (v_topic_id, 'A newborn with severe hypoglycemia, macroglossia, and hemihyperplasia is at increased risk for which tumor?', '["Neuroblastoma", "Wilms Tumor", "Retinoblastoma", "Medulloblastoma"]', 1, 'Beckwith-Wiedemann syndrome (WT2 gene alteration) involves macrosomia, macroglossia, omphalocele, and an increased risk of Wilms tumor and hepatoblastoma.'),
    (v_topic_id, 'Which of the following presents with hyperpigmentation, polyostotic fibrous dysplasia, and precocious puberty?', '["McCune-Albright Syndrome", "Neurofibromatosis Type 1", "Peutz-Jeghers Syndrome", "MEN 1"]', 0, 'McCune-Albright syndrome (mosaic G-protein signaling mutation) features café-au-lait spots (irregular borders), bone dysplasia, and endocrine hyperfunction (often precocious puberty).');

    RAISE NOTICE 'SUCCESS: Endocrine Pathology MCQs Part 2 (61-140) registered.';
END $$;

COMMIT;
